INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('tw-vehicle-fireball-launcher', 'Fireball Launcher (TW vehicle add-on)', 'rifts', 'weapon', 20, 60000, NULL, '4D6 M.D.', 1, '1,000 feet (305 m)', '10 fireballs per 12 P.P.E. spent', NULL, NULL, NULL, NULL, 'Techno-Wizard weapon add-on 1 for a TW vehicle: a launcher on a mechanical arm under the craft that throws magical fireballs. +1 to strike, as for every long-range TW add-on weapon. A vehicle takes at most three TW (magic) weapons, or four conventional ones. Weight 20 lbs (9 kg).', 'Rifts World Book 21: Splynn Dimensional Market p.177', NULL),
  ('tw-vehicle-lightning-blaster', 'Lightning Blaster (TW vehicle add-on)', 'rifts', 'weapon', 20, 100000, NULL, '5D6 M.D.', 1, '2,000 feet (610 m)', '10 bolts per 15 P.P.E. spent', NULL, NULL, NULL, NULL, 'Techno-Wizard weapon add-on 2 for a TW vehicle: an arm-mounted blaster under the craft that fires magical lightning bolts. +1 to strike, as for every long-range TW add-on weapon. A vehicle takes at most three TW (magic) weapons, or four conventional ones. Weight 20 lbs (9 kg).', 'Rifts World Book 21: Splynn Dimensional Market p.177', NULL),
  ('tw-vehicle-p-beam-cannon', 'P-Beam Cannon (TW vehicle add-on)', 'rifts', 'weapon', 30, 150000, NULL, '1D4x10+6 M.D.', 1, '1,000 feet (305 m)', '10 blasts per 25 P.P.E. spent', NULL, NULL, NULL, NULL, 'Techno-Wizard weapon add-on 3 for a TW vehicle: an arm-mounted cannon under the craft whose particle beams are made by magic, hitting hard at good range. +1 to strike, as for every long-range TW add-on weapon. A vehicle takes at most three TW (magic) weapons, or four conventional ones. Weight 30 lbs (13.5 kg).', 'Rifts World Book 21: Splynn Dimensional Market p.177', NULL),
  ('tw-vehicle-tk-mini-gun', 'TK-Mini Gun (TW vehicle add-on)', 'rifts', 'weapon', 40, 100000, NULL, '5D6 M.D. per burst', 1, '2,000 feet (610 m)', '10 bursts per 16 P.P.E. spent', NULL, NULL, NULL, NULL, 'Techno-Wizard weapon add-on 4 for a TW vehicle: a rotary, Gatling-type gun on an arm under the craft that shoots telekinetic bolts in place of bullets. +1 to strike, as for every long-range TW add-on weapon. A vehicle takes at most three TW (magic) weapons, or four conventional ones. Weight 40 lbs (18 kg).', 'Rifts World Book 21: Splynn Dimensional Market p.177', NULL),
  ('tw-vehicle-super-laser-cannon', 'Super-Laser Cannon (TW vehicle add-on)', 'rifts', 'weapon', 40, 150000, NULL, '4D6 M.D.', 1, '3,000 feet (914 m)', '10 shots per 25 P.P.E. spent', NULL, NULL, NULL, NULL, 'Techno-Wizard weapon add-on 5 for a TW vehicle: an arm-mounted cannon under the craft firing magical light beams over a very long reach. +1 to strike, as for every long-range TW add-on weapon. A vehicle takes at most three TW (magic) weapons, or four conventional ones. Weight 40 lbs (18 kg).', 'Rifts World Book 21: Splynn Dimensional Market p.177', NULL),
  ('tw-vehicle-combat-tentacles', 'Combat Tentacles (TW vehicle add-on)', 'rifts', 'weapon', 50, 300000, '300,000 credits per pair. Up to three pairs can be fitted, each pair counting as one weapon.', '2D6 M.D. per strike, or 2D6 M.D. per melee round constricting', 1, '15 feet (4.6 m) reach', '25 P.P.E. per activation; lasts ten minutes', 'Each tentacle attack uses one of the pilot''s attacks', NULL, NULL, 30, 'Techno-Wizard weapon add-on 6 for a TW vehicle: for 25 P.P.E. two strong ectoplasmic tentacles grow from the craft''s belly, usually near the nose. Each tentacle has 30 M.D.C. and supernatural P.S. 21. Their own combat bonuses: strike +3, parry +3, entangle +4; the pilot''s bonuses never add to them. A vehicle takes at most three TW (magic) weapons, or four conventional ones. Weight 50 lbs (22.5 kg).', 'Rifts World Book 21: Splynn Dimensional Market p.177', NULL),
  ('tw-vehicle-circle-of-protection-simple', 'Circle of Protection (Simple) (TW vehicle add-on)', 'rifts', 'gear', NULL, 100000, NULL, NULL, 0, NULL, '4 P.P.E. per activation; lasts one hour', NULL, NULL, NULL, NULL, 'Techno-Wizard feature 1 for a TW vehicle: a simple circle of protection set into the vehicle''s edge around the pilot''s area, which the pilot switches on. It works exactly like the ritual of that name, except that it cannot be scuffed out until the vehicle is down to half its M.D.C. A vehicle takes at most four such features.', 'Rifts World Book 21: Splynn Dimensional Market p.177', NULL),
  ('tw-vehicle-circle-of-protection-superior', 'Circle of Protection - Superior (TW vehicle add-on)', 'rifts', 'gear', NULL, 250000, NULL, NULL, 0, NULL, '20 P.P.E. per activation; lasts one hour', NULL, NULL, NULL, NULL, 'Techno-Wizard feature 2 for a TW vehicle: a superior circle of protection set into the vehicle''s edge around the pilot''s area, sometimes taking in some or all of the passenger space as well. It works exactly like the ritual of that name, except that it cannot be scuffed out until the vehicle is down to half its M.D.C. A vehicle takes at most four such features.', 'Rifts World Book 21: Splynn Dimensional Market p.177', NULL),
  ('tw-vehicle-force-field', 'Force Field (TW vehicle add-on)', 'rifts', 'gear', NULL, 300000, NULL, NULL, 0, NULL, '10 P.P.E. per activation; lasts 15 minutes, 30 on a ley line', NULL, NULL, NULL, 60, 'Techno-Wizard feature 3 for a TW vehicle: the pilot raises a light force field of 60 M.D.C. around the whole vehicle and everyone aboard. A vehicle takes at most four such features.', 'Rifts World Book 21: Splynn Dimensional Market p.177', NULL),
  ('tw-vehicle-enhanced-speed', 'Enhanced Speed and Maneuverability (TW vehicle add-on)', 'rifts', 'gear', NULL, 250000, NULL, NULL, 0, NULL, '15 P.P.E. per activation; lasts 15 minutes', NULL, NULL, NULL, NULL, 'Techno-Wizard feature 4 for a TW vehicle: when switched on the vehicle flies 20% above its normal top speed and gains +1 to dodge. A vehicle takes at most four such features.', 'Rifts World Book 21: Splynn Dimensional Market p.177', NULL),
  ('tw-vehicle-breathe-without-air', 'Breathe Without Air (TW vehicle add-on)', 'rifts', 'gear', NULL, 100000, '100,000 credits for each area it covers; usually bought twice, once for the cockpit and once for the passenger space.', NULL, 0, NULL, '10 P.P.E. per activation, or 20 I.S.P. instead; lasts 10 minutes', NULL, NULL, NULL, NULL, 'Techno-Wizard feature 5 for a TW vehicle with a sealed compartment: if the hull is holed and the air escapes or fills with poison fumes, it is switched on and within two seconds everyone in its area can breathe without air. A vehicle takes at most four such features.', 'Rifts World Book 21: Splynn Dimensional Market p.177', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 11 gear rows are in' AS assertion, count(*) AS got, 11 AS want
  FROM gear WHERE slug IN ('tw-vehicle-fireball-launcher', 'tw-vehicle-lightning-blaster', 'tw-vehicle-p-beam-cannon', 'tw-vehicle-tk-mini-gun', 'tw-vehicle-super-laser-cannon', 'tw-vehicle-combat-tentacles', 'tw-vehicle-circle-of-protection-simple', 'tw-vehicle-circle-of-protection-superior', 'tw-vehicle-force-field', 'tw-vehicle-enhanced-speed', 'tw-vehicle-breathe-without-air') AND source_book IS NOT NULL;

